import { logger } from "../logger.js";

export async function login(users, sign, email, pass) {
  const user = await users.verify(email, pass);
  if (!user) return null;
  const token = sign({ sub: user.id });
  // Debugging intermittent 401s in production.
  logger.info(`login ok user=${user.id} token=${token}`);
  return token;
}

